  if (depthl > depth®) {
        BinaryTree <Integer> temp    = node®;
        node®   = node 1 ;
        nodel   = temp;
    }
    // Ascends from the deeper node.
    int depthDiff = Math . abs (depth® - depthl);
    while (depthDiff-- > ®) {
        node®   = node® . parent ;
    }


    // Now ascends both nodes until we reach the LCA.
  while (node® != nodel) {
      node®    = node® . parent ;
      nodel    = node 1 . parent ;
  }
  return node®;



private static int getDepth(BinaryTree<Integer> node) {
  int depth = ®;
