  }
  Pr iorityQueue <ArrayEntry > minHeap = new Prior ityQueue <>(
       ((int)sort edArrays.size()), new Comparator <ArrayEntry >() {
         ©Override
         public int compare(ArrayEntry ol , ArrayEntry o2) {
            return Integer . compare(ol . value , o2. value);
         }
            });
    for (int i = Q; i < it ers . s ize(); ++i) {
      if (iters . get(i).hasNext()) {
            minHeap . add(new ArrayEntry(iters . get(i).next(), i));
        }
    }

    List <Integer> result = new ArrayLi st <>();
    while (! minHeap . isEmpty()){
      ArrayEntry headEntry = minHeap . poll();
      result . add(headEntry . value) ;
      if (iters . get(headEntry . arrayld).hasNext()){
