  Pr iorityQueue <Star > maxHeap
       = new PriorityQueue<>(k, Collections .reverseOrder());
  while (stars . hasNext()){
    // Add each star to the max -heap . If the max-heap size exceeds k, remove
    // the maximum element from the max -heap.
    Star star = stars.next();
     maxHeap . add(star);
