  int left = 8, right = A.sizeO - 1;
  while (left <= right) {
    int mid = left + ((right - left) / 2) ;
    int difference = A. get (mid) - mid;
              .
    // A get (mid) == mid if and only if difference == 8.
        if (difference == 8) {
            return mid;
        > else if (difference > 8) {
          right = mid - 1;
        } else { // difference < 8.
          left = mid + 1;
        >
    >
    return -1;
}


