  for (GraphVertex v : G) {
    if (v.d == -1) { // Unvisited vertex.
      v .d = ® ;
      if (! BFS(v)){
         return false;
          }
      }
  }
  return true ;



private static boolean BFS(GraphVertex s) {
  Queue <GraphVertex > q = new LinkedLis t <>() ;
  q . add(s);

  while (! q . isEmpty()){
    for (GraphVertex t : q . peek(). edges) {
      if (t.d == -1) { // Unvisited vertex.
        t . d = q . peek().d + 1 ;
        q . add(t);
      } else if (t.d == q.peek().d) {
              return false;
          }
      }
      q .remove();
  }
  return true ;
