      } else if (leftParenthesesIndices . isEmpty()) {
        end = i ;
      } else {
        leftParenthesesIndices . removeFirst();
        int start = leftParenthesesIndices . isEmpty()
                        ? end
                        : leftParenthesesIndices .peekFirst();
        maxLength = Math . max(maxLength , i       -
                                              start);
      }
  }
