               post order Sequence . add (curr .data) ;
              path . removeFirst () ;
          }
      } else {
          // Finished traversing left            and right, so visit curr.
          post order Sequence . add (curr .data) ;
          path . removeFirst () ;
      }
      prev      = curr;
  }
  return postorderSequence ;

