    BinaryTree tree , StringBuilder code ,
    MapcCharacter , String> huffmanEncoding){
  if (tree != null) {
    if (tree .s != null) {
      // This node is a leaf.
      huffmanEncoding . put(tree .s.c, code.toString());
    } else { // Non-leaf node.
      code . append(’©’);
